<script setup>
import {ref,onMounted} from 'vue'
import {request} from './client'
const emit=defineEmits(['back'])
const stage=ref('choose'),kind=ref(''),policy=ref({}),busy=ref(false),error=ref(''),accepted=ref(false),challenge=ref(''),code=ref(''),reference=ref('')
const form=ref({full_name:'',email:'',organization:'',organization_type:'Institute',country:'',timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,language:'English',subject:'',phone:'',website:'',job:'Owner',backup_name:'',backup_email:'',username:'',qualifications:'',tagline:''})
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function google(){await run(async()=>{const r=await request('portal_policy','google_start');const u=new URL(r.url);if(u.protocol!=='https:'||u.hostname!=='accounts.google.com')throw Error('Google sign-in is not available.');location.assign(u.href)})}
async function submit(){await run(async()=>{const r=await request('registration','request_code',{data:{...form.value,kind:kind.value,privacy_accepted:accepted.value,privacy_policy_version:policy.value.privacy_policy_version}});challenge.value=r.challenge;stage.value='verify'})}
async function verify(){await run(async()=>{const r=await request('registration','verify_code',{challenge:challenge.value,code:code.value});reference.value=r.reference;stage.value='done'})}
onMounted(()=>run(async()=>policy.value=await request('portal_policy','public',{},'GET')))
</script>
<template><main class="application-shell"><header><strong>sisu ✦</strong><button @click="emit('back')">← Back to sign in</button></header><div class="application-layout"><aside><span class="eyebrow">A PLACE FOR YOUR NEXT CHAPTER</span><h1>Good people.<br>Bright futures.<br><em>One little space.</em></h1><p>Learn something new. Share what you know. Build a community that belongs.</p><div class="application-art" aria-hidden="true">✦<span>❀</span>✧</div><small>Your profile. Your people. Your own pace.</small></aside><section class="panel application-form"><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="stage==='choose'"><span class="eyebrow">LET’S START WITH YOU</span><h2>Are you here to learn or teach?</h2><button class="application-choice" @click="stage='learner'"><strong>I’m a learner</strong><span>Find teachers, join classes and make room to grow.</span>↗</button><button class="application-choice" @click="stage='provider'"><strong>I’m here to teach</strong><span>Teach independently or bring your institute.</span>↗</button></template><template v-else-if="stage==='learner'"><h2>Your learning starts here.</h2><p>Students sign in with Google, then complete their profile and phone verification. One account can follow and join multiple teachers and institutes.</p><button class="button primary" :disabled="busy||!policy.google_available" @click="google">G · Continue with Google</button><p v-if="!policy.google_available" class="field-help">Google sign-in will appear here when the site’s Google connection is configured.</p><button class="text-button" @click="stage='choose'">Choose another path</button></template><template v-else-if="stage==='provider'"><h2>How do you teach?</h2><button class="application-choice" @click="kind='Individual Teacher';stage='details'"><strong>Individual teacher</strong><span>Your own profile, classes and institute memberships.</span>↗</button><button class="application-choice" @click="kind='Institute';stage='details'"><strong>Institute or school</strong><span>A branded workspace for your teaching community.</span>↗</button></template><form v-else-if="stage==='details'" @submit.prevent="submit"><span class="eyebrow">{{kind}} APPLICATION</span><h2>Tell us your story.</h2><p>We review every provider. Approval starts account setup; a verified badge and code follow profile and phone verification.</p><label>Your full name<input v-model="form.full_name" required maxlength="120"></label><label>Email<input v-model="form.email" type="email" required></label><label>Preferred username<input v-model="form.username" pattern="[a-z][a-z0-9_]{2,29}" maxlength="30" required></label><label>Phone number<input v-model="form.phone" type="tel" pattern="\+[1-9][0-9]{7,14}" required placeholder="+94…"></label><p class="field-help">You will verify this number by SMS during secure account setup.</p><template v-if="kind==='Institute'"><label>Institute name<input v-model="form.organization" required maxlength="120"></label><label>Your position<input v-model="form.job" required maxlength="120"></label><label>Recovery contact name<input v-model="form.backup_name" required></label><label>Recovery contact email<input v-model="form.backup_email" type="email" required></label></template><label v-else>Subject / expertise<input v-model="form.subject" required maxlength="120"></label><label>Qualifications<input v-model="form.qualifications" maxlength="240"></label><label>Tagline<input v-model="form.tagline" maxlength="120"></label><label>Country<input v-model="form.country" required></label><label>Time zone<input v-model="form.timezone" required></label><label>Website (optional)<input v-model="form.website" type="url"></label><label v-if="policy.privacy_policy_url" class="application-consent"><input v-model="accepted" type="checkbox" required>I agree to the <a :href="policy.privacy_policy_url" target="_blank" rel="noopener noreferrer">privacy policy</a> ({{policy.privacy_policy_version}}).</label><div v-else class="application-policy">Privacy policy space reserved.<br>The Sisu team will add its published policy here before accepting applications.</div><button class="button primary" :disabled="busy||!accepted||!policy.provider_applications_enabled">Verify email & submit application</button><button type="button" class="text-button" @click="stage='provider'">Back</button></form><form v-else-if="stage==='verify'" @submit.prevent="verify"><h2>A little check, just for you.</h2><p>Enter the six-digit code sent to {{form.email}}. It expires in ten minutes.</p><label>Email verification code<input v-model="code" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required></label><button class="button primary" :disabled="busy">Verify & send for review</button></form><template v-else><h2>Your application is with us.</h2><p>Reference: {{reference}}. After approval, use the secure setup email to create your password, then verify your phone and complete your profile.</p></template></section></div></main></template>
<style>.application-shell{min-height:100vh;padding:30px 6vw;background:#f5effb;color:#443650}.application-shell header{display:flex;justify-content:space-between;align-items:center}.application-shell header strong{font-size:34px}.application-layout{display:grid;grid-template-columns:1fr 1fr;gap:7vw;max-width:1200px;margin:60px auto}.application-layout aside{padding-top:30px}.application-layout h1{font-size:54px;line-height:1.2;margin:24px 0}.application-layout em{font-style:normal;color:#9875b9}.application-layout p{font-size:14px;margin:20px 0;line-height:1.8}.application-art{font-size:70px;color:#a38ac0;padding:40px;text-align:center}.application-art span{font-size:140px;color:#b8cbbc}.application-form{padding:36px}.application-form h2{font-size:25px;margin:16px 0}.application-choice{display:grid;grid-template-columns:1fr auto;gap:12px;width:100%;text-align:left;padding:22px;margin:18px 0;border:1px solid #ded0ed;border-radius:20px;background:#f7f2fc}.application-choice strong{font-size:17px}.application-choice span{grid-column:1;font-size:12px;line-height:1.8;color:#82708f}.application-form label{display:grid;gap:8px;font-size:12px;margin:18px 0}.application-form input{padding:13px;border:1px solid #dfd1ec;border-radius:12px;min-width:0;background:#fffcff;color:#554464}.application-form .application-consent{display:flex;align-items:center;flex-wrap:wrap;line-height:1.7}.application-consent a{text-decoration:underline}.application-policy{background:#f2e9fa;padding:18px;border-radius:15px;font-size:12px;line-height:1.8;margin:20px 0}.application-form .text-button{display:block;margin-top:20px}@media(max-width:760px){.application-layout{grid-template-columns:1fr;gap:20px;margin:30px auto}.application-layout h1{font-size:36px}.application-art,.application-layout aside small{display:none}.application-form{padding:25px}}</style>
